using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class AgentDeactivationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public AgentDeactivationTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
        Store.Reset();
    }

    [Fact]
    public async Task DeactivatedAgentExcludedFromListUnlessIncluded()
    {
        var client = _factory.CreateClient();
        var agentResp = await client.PostAsJsonAsync("/api/agents", new { name = "Ada", email = "a@example.com" });
        var agent = await agentResp.Content.ReadFromJsonAsync<Agent>();
        await client.PostAsync($"/api/agents/{agent!.Id}/deactivate", null);

        var list = await client.GetFromJsonAsync<List<Agent>>("/api/agents");
        Assert.Empty(list!);

        var withInactive = await client.GetFromJsonAsync<List<Agent>>("/api/agents?includeInactive=true");
        Assert.Single(withInactive!);
    }

    [Fact]
    public async Task DeactivatedAgentRejectsCreationAndReassignment()
    {
        var client = _factory.CreateClient();
        var agentResp = await client.PostAsJsonAsync("/api/agents", new { name = "Ada", email = "a@example.com" });
        var agent = await agentResp.Content.ReadFromJsonAsync<Agent>();

        var unassignedResp = await client.PostAsJsonAsync("/api/tickets", new { subject = "A" });
        var unassigned = await unassignedResp.Content.ReadFromJsonAsync<Ticket>();

        await client.PostAsync($"/api/agents/{agent!.Id}/deactivate", null);

        var rejectedCreate = await client.PostAsJsonAsync("/api/tickets", new { subject = "B", agentId = agent.Id });
        Assert.Equal(HttpStatusCode.BadRequest, rejectedCreate.StatusCode);

        var rejectedReassign = await client.PatchAsJsonAsync($"/api/tickets/{unassigned!.Id}", new { agentId = agent.Id });
        Assert.Equal(HttpStatusCode.BadRequest, rejectedReassign.StatusCode);
    }
}

